mapper.select:
SELECT a.`id` `id`, a.`title` `title`, a.`notice_time` `noticeTime`, a.`content` `content`, a.`create_by` `createBy`, a.`creator_id` `creatorId`, a.`creator_type` `creatorType`, a.`level` `level`, a.`type` `type`, b.`type_name` `typeName`, a.`viewed`, a.`is_topping`, a.`status`, b.`one_level_type` as `firstType` FROM `announcement` a LEFT JOIN `model_type` b ON a.`type` = b.`id`
and a.`status` = #{query.status}
and a.`title` like #{keywordLike}
and a.`type` =#{query.type}
and a.`level` =#{query.level}
and a.`notice_time` BETWEEN #{query.period.begin} and #{query.period.end}
order by a.`is_topping` DESC, a.`notice_time` DESC

SELECT an.`id`, an.`title`, an.`level`, an.`content`, an.`create_by`, p.`type_name` `publish_agency`, t.`type_name` `tag_name`, mt.`type_name` `type_name`, an.`create_time` FROM `announcement` an INNER JOIN `model_type` mt ON mt.`id` = an.`type` LEFT JOIN `model_type` p ON p.`id` = an.`publish_agency` LEFT JOIN `model_type` t ON t.`id` = an.`tag_id`
and an.`status` = #{command.status}
and t.`type_name` = #{command.tagType}
and an.`title` like #{keywordLike}
and mt.`one_level_type` = #{command.informationType}
ORDER BY an.`is_topping` DESC, an.`notice_time` DESC
